def seq(k, N=6):
    a = [k]
    for n in range(1, N):
        a.append(a[-1] - k - n if a[-1] > 0 else a[-1] + 3 * n - k)
    return a

def skill():
    tot = 0
    for k in range(1, 12):
        a3 = 5 - k
        a4 = a3 + 9 - k if a3 <= 0 else a3 - k - 3
        a5 = a4 + 12 - k if a4 <= 0 else a4 - k - 4
        a6 = a5 + 15 - k if a5 <= 0 else a5 - k - 5
        if a3 * a4 * a5 * a6 < 0:
            tot += k
    return tot

def standard():
    return sum(k for k in range(1, 300) if seq(k)[2] * seq(k)[3] * seq(k)[4] * seq(k)[5] < 0)

def unique():
    return [sum(k for k in range(1, 3000) if seq(k)[2] * seq(k)[3] * seq(k)[4] * seq(k)[5] < 0)]
